/* ===== Swing trading B: candlestick patterns & chart patterns ===== */

STT('st-cs-single', { name: 'Single-candle patterns', cat: 'stcandle',
  blurb: `Some single candles signal exhaustion or rejection strongly enough to matter — but only in the right place. The hammer, shooting star, doji and marubozu are the core single-candle shapes. Each is a story about who won the period; location and confirmation decide whether to act.`,
  facts: [['Hammer', 'rejection of lows (bullish, at support)'], ['Shooting star', 'rejection of highs (bearish, at resistance)'], ['Doji', 'indecision / balance'], ['Marubozu', 'total control, no wicks']],
  cheat: [['Hammer', 'Small body on top, long lower wick, after a downtrend → bullish'], ['Inverted hammer', 'Small body bottom, long upper wick, after a downtrend → bullish hint'], ['Shooting star', 'Small body bottom, long upper wick, after an uptrend → bearish'], ['Hanging man', 'Small body top, long lower wick, after an uptrend → bearish hint'], ['Doji', 'Open ≈ close; indecision; turning hint in context'], ['Spinning top', 'Small body, wicks both sides; indecision'], ['Marubozu', 'Long body, no/tiny wicks; one side dominated'], ['Location is key', 'Same shape means nothing mid-range'], ['Confirm', 'Next candle in the signal’s direction'], ['Volume', 'Higher volume strengthens the signal']],
  sections: [
    ['Hammer vs shooting star — mirror rejections', FIG2(
      FIG(chart({ w: 270, h: 200, candles: [[12, 12.1, 11.3, 11.4], [11.4, 11.5, 10.6, 10.7], [10.7, 10.85, 9.6, 10.6]], axis: false, notes: [{ i: 2, p: 9.4, text: 'hammer', anchor: 'middle' }] }), 'Hammer after a downtrend: long lower wick = buyers rejected lower prices. Bullish at support.'),
      FIG(chart({ w: 270, h: 200, candles: [[10, 10.9, 9.9, 10.8], [10.8, 11.7, 10.7, 11.6], [11.6, 12.65, 11.5, 11.6]], axis: false, notes: [{ i: 2, p: 12.85, text: 'shooting star', anchor: 'middle' }] }), 'Shooting star after an uptrend: long upper wick = sellers rejected higher prices. Bearish at resistance.'))],
    ['Doji and marubozu — indecision vs conviction', FIG2(
      FIG(chart({ w: 270, h: 190, candles: [[10, 10.7, 9.3, 10.05]], axis: false, notes: [{ i: 0, p: 9.1, text: 'doji', anchor: 'middle' }] }), 'Doji: open ≈ close. Neither side won — balance. After a strong trend it hints at a pause or turn.'),
      FIG(chart({ w: 270, h: 190, candles: [[10, 11.05, 9.98, 11.0]], axis: false, notes: [{ i: 0, p: 9.7, text: 'marubozu', anchor: 'middle' }] }), 'Bullish marubozu: a long body with almost no wicks — buyers controlled the entire period.'))],
    ['What each shape is saying', TBL(['Pattern', 'The story', 'Best location'], [['Hammer', 'Price dropped hard but buyers slammed it back up by the close', 'At support, after a decline'], ['Shooting star', 'Price rallied hard but sellers crushed it back by the close', 'At resistance, after a rally'], ['Doji / spinning top', 'Buyers and sellers fought to a draw — momentum is stalling', 'After an extended move'], ['Marubozu', 'One side was in complete control all period — strong momentum', 'Breakouts, trend continuation']]) + PP(`A hammer in the <i>middle</i> of a range is noise; the same hammer at a tested support after a decline is a signal. <b>Location is everything.</b>`)],
    ['How to use them (preview)', UL([`Treat single candles as <b>hints that need context</b>: a reversal candle at a key level, in line with a higher-timeframe setup, is worth acting on.`, `Wait for <b>confirmation</b> — the next candle moving in the signalled direction — before committing.`, `Check <b>volume</b>: a hammer or star on high volume carries more weight.`, `Full entry/stop mechanics are in the "Trading candlestick patterns" page.`])]
  ],
  edge: [`A hammer or star in the middle of a range (not at a level) is meaningless — location first.`, `Acting on the candle before it closes is a trap; the shape can change entirely by the close.`, `No confirmation = higher failure rate; many reversal candles fail without a follow-through candle.`, `A doji is indecision, not a direction — it says "pause," and needs context to mean reversal.`, `Low-volume reversal candles are weak; the same shape on heavy volume is far more reliable.`],
  faq: [['What is the difference between a hammer and a hanging man?', PP(`They are the <b>same shape</b> (small body on top, long lower wick) — the difference is <b>location</b>. After a <i>downtrend</i> at support it is a <b>hammer</b> (bullish: buyers rejected lows). After an <i>uptrend</i> at resistance the identical shape is a <b>hanging man</b> (bearish: a warning that selling appeared). This is the clearest proof that context, not shape alone, defines a candlestick signal.`)],
    ['Does a doji mean the trend will reverse?', PP(`Not by itself — a doji means <b>indecision</b>: buyers and sellers finished even. After a strong trend it <i>hints</i> momentum is stalling and a turn may be near, but plenty of dojis are just pauses before the trend resumes. Treat it as a "pay attention" flag and wait for the next candle(s) to confirm a direction before trading it.`)],
    ['How important is volume on these candles?', PP(`Quite important. A rejection candle (hammer/star) on <b>high volume</b> means many participants took part in the reversal — more trustworthy. The same shape on thin volume may be a random wick. Make volume a standard confirmation: strong signal candles usually come with a volume spike.`)]],
  qs: [SQ('A candle with a small body on top and a long lower wick, appearing at support after a decline, is a…', ['Shooting star', 'Hammer (bullish rejection of lows)', 'Marubozu', 'Doji'], 1, 'Long lower wick = buyers rejected lower prices; at support after a decline it is a bullish hammer.'),
    SQ('The hammer and hanging man have the same shape. What makes them different signals?', ['The colour', 'Their location — hammer after a downtrend (bullish), hanging man after an uptrend (bearish)', 'The volume', 'Nothing, they are identical signals'], 1, 'Identical shape; the trend context before it flips the meaning.')]
});
DP('st-cs-single', {
  fu: [['Why does the same candle shape mean opposite things in different places?', 'A candlestick is a snapshot of a battle; its significance comes from where the battle happens. A long lower wick after a decline at support means buyers defended a key floor (bullish); the same wick mid-trend is just noise. Context supplies the meaning the shape alone cannot.'],
    ['What is confirmation and why wait for it?', 'Confirmation is the next candle (or a break of the signal candle’s high/low) moving in the signalled direction. Waiting filters out failed signals — many reversal candles do not follow through — at the cost of a slightly later entry. The reliability gain is usually worth it.'],
    ['Is a bigger wick always better?', 'A longer wick shows stronger rejection, which is generally better — but an enormous wick can also reflect a volatile, news-driven spike that is hard to trade. Weigh wick length with volume, location and the follow-through, not in isolation.']],
  deep: [['Technique', 'Score a single-candle signal by three filters: is it at a key level, is it against an over-extended move, and is volume elevated? Only act when at least location plus one more align, and wait for confirmation.'],
    ['Failure mode', 'Trading every hammer/star on sight regardless of location, or entering before the candle closes (the shape can vanish).'],
    ['In real charts', 'Reversal candles cluster at tested support/resistance and trend extremes; the most reliable are large-wicked candles on a volume spike right at a higher-timeframe level.']],
  src: ['StockCharts ChartSchool: Candlestick Bullish/Bearish Reversals', 'https://chartschool.stockcharts.com/table-of-contents/chart-analysis/introduction-to-candlesticks/candlesticks-and-support'] });

STT('st-cs-double', { name: 'Two-candle patterns', cat: 'stcandle',
  blurb: `Two-candle patterns pack a clearer story than one: the second candle overwhelms or reverses the first. Engulfing, harami, tweezers, piercing and dark-cloud patterns are the workhorses — especially the engulfing, one of the most reliable candlestick reversals.`,
  facts: [['Engulfing', 'candle 2 swallows candle 1 (strong)'], ['Harami', 'candle 2 inside candle 1 (pause)'], ['Tweezers', 'matching highs/lows → rejection'], ['Best at', 'support/resistance after a move']],
  cheat: [['Bullish engulfing', 'Big green body fully engulfs prior red → bullish reversal'], ['Bearish engulfing', 'Big red body fully engulfs prior green → bearish reversal'], ['Bullish harami', 'Small green inside prior big red → downtrend stalling'], ['Bearish harami', 'Small red inside prior big green → uptrend stalling'], ['Tweezer bottom', 'Two candles with matching lows → support/rejection'], ['Tweezer top', 'Two candles with matching highs → resistance/rejection'], ['Piercing line', 'Red then green closing >50% into the red → bullish'], ['Dark cloud cover', 'Green then red closing >50% into the green → bearish'], ['Engulf strength', 'Bigger engulfing body + volume = stronger'], ['Location', 'At a level, after a trend — not mid-range']],
  sections: [
    ['Engulfing — the heavyweight reversal', FIG2(
      FIG(chart({ w: 270, h: 200, candles: [[11, 11.1, 10.1, 10.2], [10.1, 11.5, 10.0, 11.45]], axis: false, notes: [{ i: 1, p: 9.8, text: 'bullish engulfing', anchor: 'middle' }] }), 'Bullish engulfing: a large green candle completely engulfs the prior red one — buyers took over.'),
      FIG(chart({ w: 270, h: 200, candles: [[10.2, 11.1, 10.1, 11.0], [11.1, 11.2, 9.8, 9.9], ], axis: false, notes: [{ i: 1, p: 9.6, text: 'bearish engulfing', anchor: 'middle' }] }), 'Bearish engulfing: a large red candle engulfs the prior green one — sellers took over.'))],
    ['Harami and tweezers', FIG2(
      FIG(chart({ w: 270, h: 200, candles: [[12, 12.1, 10.3, 10.4], [10.7, 11.1, 10.6, 11.0]], axis: false, notes: [{ i: 1, p: 10.2, text: 'bullish harami', anchor: 'middle' }] }), 'Bullish harami: a small candle sits inside the prior large red body — selling momentum is stalling.'),
      FIG(chart({ w: 270, h: 200, candles: [[11, 11.1, 9.6, 9.7], [9.75, 10.8, 9.6, 10.6]], axis: false, notes: [{ i: 0.5, p: 9.42, text: 'tweezer bottom (matching lows)', anchor: 'middle' }] }), 'Tweezer bottom: two candles reject the same low — buyers defended that level twice.'))],
    ['The patterns compared', TBL(['Pattern', 'Candle 1', 'Candle 2', 'Signals'], [['Bullish engulfing', 'Small red', 'Big green engulfing it', 'Strong bullish reversal'], ['Bearish engulfing', 'Small green', 'Big red engulfing it', 'Strong bearish reversal'], ['Bullish harami', 'Big red', 'Small candle inside it', 'Downtrend losing steam'], ['Bearish harami', 'Big green', 'Small candle inside it', 'Uptrend losing steam'], ['Tweezer bottom/top', 'Candle rejecting a level', 'Candle rejecting same level', 'Double rejection at a price']]) + PP(`<b>Engulfing</b> is a momentum <i>flip</i> (the other side seized control); <b>harami</b> is a momentum <i>pause</i> (the trend stalled but hasn’t flipped). Engulfing is the stronger, more actionable signal.`)],
    ['Making them tradable', UL([`<b>Location:</b> a bullish engulfing at tested support after a decline is strong; mid-range it is noise.`, `<b>Size & close:</b> the bigger the engulfing body and the stronger its close, the more conviction.`, `<b>Volume:</b> a reversal candle on a volume spike is far more reliable.`, `<b>Entry/stop:</b> typically enter on the next candle / a break of the pattern, with the stop just beyond the pattern’s extreme (details in the trading page).`])]
  ],
  edge: [`An engulfing or harami mid-range (no level, no prior trend) is low-value — it needs location and a preceding move to reverse.`, `A "bullish engulfing" that only engulfs the body but not the wicks, on low volume, is weak — demand a convincing engulf.`, `Harami signals a pause, not a reversal — don’t treat it as a confirmed flip; wait for follow-through.`, `Tweezers need the matching highs/lows to be at a meaningful level to count.`, `As always, wait for the candle to close and ideally for confirmation before entering.`],
  faq: [['Why is the engulfing pattern considered strong?', PP(`Because the second candle <b>completely overwhelms</b> the first: buyers (or sellers) not only stopped the prior move but reversed it within one period, erasing the previous candle entirely. That decisive flip of control, especially at a key level and on strong volume, is why bullish/bearish engulfing is among the most-watched and more reliable candlestick reversals.`)],
    ['Engulfing vs harami — when is each useful?', PP(`<b>Engulfing</b> says control has <i>flipped</i> — the other side seized the period — so it is a reversal signal you can act on (with location/confirmation). <b>Harami</b> says the trend has <i>paused</i>: a small candle inside the prior large one shows momentum drying up, but not yet a reversal. Use engulfing to trade turns; use harami as an early warning to tighten stops or wait for an engulfing/break to confirm.`)],
    ['Does the engulfing candle need to engulf the wicks too?', PP(`The classic definition requires the second <b>body</b> to engulf the prior <b>body</b>; engulfing the wicks as well makes it even stronger. A candle that engulfs only part of the body, or barely closes past it, is a weak version. Prefer clear, decisive engulfings with a strong close and supporting volume.`)]],
  qs: [SQ('A large green candle completely engulfs the prior small red candle at support. This is a…', ['Bearish engulfing', 'Bullish engulfing (strong bullish reversal)', 'Harami', 'Doji'], 1, 'Candle 2 engulfing candle 1 in the bullish direction at support is a strong reversal signal.'),
    SQ('What does a harami primarily signal?', ['A confirmed reversal', 'A pause / loss of momentum in the current trend, not yet a flip', 'A breakout', 'Nothing'], 1, 'A small candle inside the prior large one shows the trend stalling — a pause, pending confirmation.')]
});
DP('st-cs-double', {
  fu: [['What are piercing line and dark cloud cover?', 'Two-candle reversals that fall short of a full engulf. Piercing line (bullish): a red candle, then a green that opens lower but closes back above the midpoint of the red body. Dark cloud cover (bearish): a green candle, then a red that opens higher but closes below the green’s midpoint. Weaker than engulfing but similar logic.'],
    ['Why does location dominate candlestick reliability?', 'Candlesticks reflect short-term order flow; they resolve best when they coincide with where larger forces act — tested support/resistance, trend extremes, confluence. The same pattern’s success rate is far higher at a key level than in open space.'],
    ['How do you set a stop on a two-candle reversal?', 'Typically just beyond the pattern’s extreme — below the engulfing/tweezer low for a long, above it for a short. If price closes back through that extreme, the reversal failed and you want out. Exact sizing is in the stop-loss unit.']],
  deep: [['Technique', 'Rank two-candle signals: engulfing > piercing/dark cloud > harami, all amplified by location, body size, close strength and volume. Enter on confirmation (next candle or break of the pattern), stop beyond the extreme.'],
    ['Failure mode', 'Trading engulfings/haramis in open range with no level or prior trend, or on thin volume — high failure rate.'],
    ['In real charts', 'Bullish/bearish engulfing at a well-tested level on a volume spike is a staple reversal entry; harami more often precedes a pause that an engulfing later confirms.']],
  src: ['StockCharts ChartSchool: Candlestick Patterns', 'https://chartschool.stockcharts.com/table-of-contents/chart-analysis/introduction-to-candlesticks'] });

STT('st-cs-triple', { name: 'Three-candle patterns', cat: 'stcandle',
  blurb: `Three-candle patterns tell a complete reversal or continuation story: a trend, a turning point, and a confirmation — all visible at once. Morning and evening stars are the premier reversals; three soldiers/crows show powerful continuation or exhaustion.`,
  facts: [['Morning star', '3-candle bullish bottom reversal'], ['Evening star', '3-candle bearish top reversal'], ['Three soldiers/crows', 'strong directional thrust'], ['Strength', 'more candles = clearer story']],
  cheat: [['Morning star', 'Big red → small indecision candle → big green → bullish reversal'], ['Evening star', 'Big green → small indecision candle → big red → bearish reversal'], ['Three white soldiers', 'Three strong rising green candles → bullish thrust'], ['Three black crows', 'Three strong falling red candles → bearish thrust'], ['Three inside up/down', 'Harami + confirmation candle'], ['Middle candle', 'The indecision/turn (often a doji/small body)'], ['Confirmation built-in', 'The 3rd candle is the confirmation'], ['Volume', 'Rising volume on the thrust strengthens it'], ['Location', 'Stars at S/R or trend extremes'], ['Exhaustion', 'Soldiers/crows after a long move can mark a climax']],
  sections: [
    ['Morning star and evening star', FIG2(
      FIG(chart({ w: 270, h: 210, candles: [[12, 12.1, 11.0, 11.1], [10.8, 10.95, 10.45, 10.6], [10.7, 12.05, 10.6, 11.95]], axis: false, notes: [{ i: 1, p: 10.25, text: 'morning star', anchor: 'middle' }] }), 'Morning star (bullish bottom): a big down candle, a small indecision candle, then a big up candle that recovers into the first — the turn is complete.'),
      FIG(chart({ w: 270, h: 210, candles: [[10, 11.1, 9.95, 11.0], [11.2, 11.5, 11.05, 11.3], [11.2, 11.3, 10.0, 10.05]], axis: false, notes: [{ i: 1, p: 9.75, text: 'evening star', anchor: 'middle' }] }), 'Evening star (bearish top): a big up candle, a small indecision candle, then a big down candle that erases the gains — the top is in.'))],
    ['Three soldiers and three crows', FIG2(
      FIG(chart({ w: 270, h: 200, candles: [[10, 10.8, 9.95, 10.7], [10.7, 11.5, 10.65, 11.4], [11.4, 12.2, 11.35, 12.1]], axis: false, notes: [{ i: 1, p: 9.75, text: 'three white soldiers', anchor: 'middle' }] }), 'Three white soldiers: three strong rising candles — decisive bullish momentum.'),
      FIG(chart({ w: 270, h: 200, candles: [[12, 12.05, 11.2, 11.3], [11.3, 11.35, 10.5, 10.6], [10.6, 10.65, 9.8, 9.9]], axis: false, notes: [{ i: 1, p: 9.6, text: 'three black crows', anchor: 'middle' }] }), 'Three black crows: three strong falling candles — decisive bearish momentum.'))],
    ['Reading the three-candle story', TBL(['Pattern', 'The three beats', 'Signals'], [['Morning star', 'Selling → indecision → buying takes over', 'Bullish reversal (bottom)'], ['Evening star', 'Buying → indecision → selling takes over', 'Bearish reversal (top)'], ['Three white soldiers', 'Three decisive up candles in a row', 'Strong bullish continuation/reversal from a base'], ['Three black crows', 'Three decisive down candles in a row', 'Strong bearish continuation/reversal from a top']]) + PP(`The strength of three-candle patterns is that <b>confirmation is built in</b>: the third candle is the follow-through. A morning star already shows buyers winning, so you need less extra confirmation than for a single candle.`)],
    ['Using them well', UL([`<b>Stars at levels/extremes:</b> a morning star at tested support after a decline is a high-quality bottom signal; an evening star at resistance after a rally marks tops.`, `<b>Soldiers/crows:</b> great for confirming a breakout or the start of a trend — but after a <i>long</i> run they can be a climactic <b>exhaustion</b>, so beware chasing the third candle.`, `<b>Volume</b> rising through the pattern strengthens it.`, `<b>Entry</b> is often on/after the third candle’s close with a stop beyond the pattern’s extreme.`])]
  ],
  edge: [`Chasing the <i>third</i> soldier/crow after a long run can buy/sell right into exhaustion — the move may be nearly over.`, `A morning/evening star needs the third candle to recover well into the first; a weak third candle makes it unreliable.`, `Mid-range three-candle patterns (no level, no trend) carry little weight.`, `Gaps in the classic star definitions are common in stocks but rarer in 24/7 markets like crypto/forex — the pattern still works with small-bodied middles.`, `Entering before the third candle closes risks the pattern not completing.`],
  faq: [['Why are morning/evening stars considered reliable reversals?', PP(`Because they show the full turn in three beats: the trend in force, a <b>loss of momentum</b> (the small middle candle), and then <b>the other side taking over</b> (a large candle recovering into the first). That built-in sequence — including its own confirmation — makes stars more trustworthy than a lone reversal candle, especially at a key level with rising volume.`)],
    ['Are three white soldiers always bullish?', PP(`They show strong bullish momentum, which is bullish from a <b>base or breakout</b>. But after an extended rally, three big green candles can be a <b>buying climax</b> — the last of the buyers piling in before exhaustion. Context matters: soldiers early in a move are continuation; soldiers after a long run can mark a top. Don’t chase the third one blindly.`)],
    ['Does the middle candle of a star have to be a doji?', PP(`It should be a <b>small-bodied candle</b> (indecision) — a doji is the textbook version, but any small body that shows momentum stalling works. In 24/7 markets the classic gaps around the middle candle are rare, so you rely on the small body plus the strong third candle rather than gaps.`)]],
  qs: [SQ('A big red candle, then a small indecision candle, then a big green candle recovering into the first, at support, is a…', ['Evening star', 'Morning star (bullish reversal)', 'Three black crows', 'Doji'], 1, 'That three-beat sequence (selling → indecision → buying) at support is a morning star.'),
    SQ('Three strong green candles after an already long rally may indicate…', ['A guaranteed continuation', 'Possible buying climax / exhaustion — be cautious chasing', 'A bearish engulfing', 'Nothing unusual'], 1, 'Late in a move, three soldiers can be the last buyers piling in before exhaustion.')]
});
DP('st-cs-triple', {
  fu: [['What are three inside up / three inside down?', 'A harami (two candles) plus a third confirming candle. Three inside up: big red, small candle inside it, then a green candle closing above the first candle’s open — a confirmed bullish reversal. The third candle supplies the confirmation the harami lacked.'],
    ['How do gaps affect star patterns?', 'Classic morning/evening stars gap around the small middle candle (common in stocks with overnight sessions). In 24/7 markets gaps are rare, so the pattern appears without them — a small-bodied middle and a strong third candle are what matter.'],
    ['Where do you place the stop on a star?', 'Below the low of a morning star (for a long) or above the high of an evening star (for a short) — if price violates the pattern’s extreme, the reversal failed. Size the position so that distance is an acceptable risk.']],
  deep: [['Technique', 'Treat the third candle as your confirmation and entry trigger; stop beyond the pattern extreme. Weight by location (S/R, trend extreme) and whether volume rose through the pattern.'],
    ['Failure mode', 'Chasing the third soldier/crow into exhaustion, or trading a star whose third candle only weakly recovers into the first.'],
    ['In real charts', 'Morning/evening stars at major levels are high-quality reversal signals; soldiers/crows best confirm the <i>start</i> of a move, not its end.']],
  src: ['StockCharts ChartSchool: Candlestick Reversal Patterns', 'https://chartschool.stockcharts.com/table-of-contents/chart-analysis/introduction-to-candlesticks'] });

STT('st-cs-trading', { name: 'Trading candlestick patterns (location, confirmation, risk)', cat: 'stcandle',
  blurb: `Patterns are only half the trade. This page turns a recognised candle into an actual plan: where it must appear to count, how to confirm it, exactly where to enter, where the stop goes, and why most pattern failures come from ignoring location.`,
  facts: [['Rule 1', 'location (at a level) comes first'], ['Rule 2', 'confirm before entering'], ['Entry', 'break of the pattern / next candle'], ['Stop', 'just beyond the pattern extreme']],
  cheat: [['Location', 'Pattern must sit at S/R, trendline, or trend extreme'], ['Confluence', 'More reasons at that price = higher odds'], ['Confirmation', 'Next candle / break of pattern high (long) or low (short)'], ['Entry (long)', 'Break of the reversal candle’s high, or next-candle open'], ['Stop (long)', 'Below the pattern’s low (the rejection wick)'], ['Target', 'Next S/R level; measure in R'], ['Volume', 'Spike on the signal candle = stronger'], ['With the trend', 'Pattern in the higher-TF direction is stronger'], ['Failure', 'Close back through the pattern = exit'], ['Skip', 'Mid-range patterns with no level']],
  sections: [
    ['The three filters a pattern must pass', OL([`<b>Location:</b> does it sit at a meaningful level — support/resistance, a trendline, a prior swing, or a trend extreme? If it is floating mid-range, skip it.`, `<b>Context/trend:</b> is it <i>with</i> the higher-timeframe bias (a bullish reversal at support within an uptrend), or fighting it? With-trend patterns are stronger.`, `<b>Confirmation:</b> has the next candle (or a break of the pattern’s extreme) moved in the signalled direction? Wait for it.`]) + PP(`A pattern that passes all three is tradable; one that passes none is noise. Most "candlesticks don’t work" complaints come from trading shapes that failed these filters.`)],
    ['Entry, stop and target, drawn', FIG(chart({ w: 560, h: 260, candles: [[24, 24.1, 23.0, 23.1], [23.1, 23.2, 22.1, 22.2], [22.2, 22.35, 21.2, 22.25], [22.3, 23.2, 22.2, 23.1], [23.1, 23.6, 22.9, 23.5], [23.5, 24.0, 23.3, 23.9]],
      hlines: [{ p: 22.1, label: 'support zone', cls: 'stc-sup' }],
      marks: [{ i: 3, p: 22.45, type: 'buy', label: 'entry: break of hammer high' }, { i: 0, p: 21.1, type: 'stop', label: 'stop: below wick' }, { i: 0, p: 24.3, type: 'target', label: 'target: next resistance' }] }),
      'A hammer forms at support (candle 3). Entry on the break of its high; stop just below its wick; target the next resistance. Risk = entry − stop; reward = target − entry.')],
    ['Where the stop goes (and why)', PP(`The stop belongs <b>just beyond the point that proves the pattern wrong</b>. For a bullish reversal that is <b>below the pattern’s low</b> (the rejection wick): if price trades back below there, buyers failed and the idea is dead, so you exit small. Placing the stop <i>inside</i> the pattern gets you shaken out by noise; placing it far away ruins your reward-to-risk. The pattern itself defines a natural, logical stop — one of the reasons candlesticks are useful for <b>risk</b>, not just entries.`)],
    ['Putting it together', UL([`<b>Measure the trade before taking it:</b> risk (entry − stop) vs reward (target − entry). If it is not at least ~1.5–2× reward-to-risk, skip it (see the risk units).`, `<b>Confluence boosts odds:</b> a reversal candle where support + a trendline + a round number meet is far stronger than at a lone level.`, `<b>With the trend</b> beats counter-trend: a bullish candle at support in an uptrend is a higher-probability pullback entry.`, `<b>Manage it:</b> if it works, consider trailing the stop; if price closes back through the pattern, respect the stop.`])]
  ],
  edge: [`The #1 mistake: trading patterns mid-range with no level — location is the first filter, not an afterthought.`, `Skipping confirmation to "get a better price" raises the failure rate sharply.`, `Stops placed inside the pattern get wicked out; stops placed far away wreck reward-to-risk — put them just beyond the pattern extreme.`, `A great pattern with a poor reward-to-risk (target too close, stop too far) is still a bad trade — measure first.`, `Counter-trend reversal patterns fail more often; favour with-trend setups until experienced.`],
  faq: [['Why do so many people say candlestick patterns “don’t work”?', PP(`Usually because they trade the <b>shape in isolation</b> — a hammer anywhere, with no level, trend, confirmation or volume. Candlesticks are context-dependent signals about short-term order flow; at a tested level, with the trend, confirmed, and on good volume, their odds improve markedly. The pattern is a trigger, not a complete trade — location and risk management do the heavy lifting.`)],
    ['Enter on the pattern candle or wait?', PP(`For higher reliability, wait for <b>confirmation</b>: enter on a break of the reversal candle’s extreme (its high for a long) or on the next candle moving your way. Entering on the pattern candle before it closes risks it morphing into something else. The trade-off is a slightly later, slightly worse entry for a meaningfully higher success rate — usually worth it while learning.`)],
    ['How do I set the target?', PP(`Use <b>structure</b>: the next resistance (for a long) or support (for a short) is a logical target where price often stalls. Then check the <b>reward-to-risk</b>: if the distance to that target is less than ~1.5–2× your risk (entry to stop), the trade is not worth taking even with a great pattern. Some traders scale out — taking partial profit at the first level and trailing the rest.`)]],
  qs: [SQ('What is the first thing to check before trading a candlestick pattern?', ['Its colour', 'Whether it sits at a meaningful level (location)', 'The time of day', 'How big the body is'], 1, 'Location (a level, trendline, or extreme) is the first filter; mid-range patterns are noise.'),
    SQ('For a bullish reversal candle at support, the stop loss belongs…', ['Far below, for safety', 'Just below the pattern’s low (the rejection wick)', 'Above the entry', 'At the target'], 1, 'Below the pattern low is where the idea is proven wrong — a tight, logical stop.')]
});
DP('st-cs-trading', {
  fu: [['How does confluence change the trade?', 'Each extra aligned reason (support + trendline + round number + with-trend) raises the probability and often lets you use a tighter, better-defined stop — improving both win rate and reward-to-risk. Confluence is why some setups are "A+" and most are skippable.'],
    ['Should I scale out or exit all at once at the target?', 'Both are valid. Exiting all at the target is simple and keeps expectancy clean. Scaling out (partial at the first level, trail the rest) can capture bigger moves while locking in profit, at the cost of a smaller average win on runners. Pick one approach and journal it consistently.'],
    ['What invalidates a pattern after entry?', 'A close back beyond the pattern’s key level/extreme — e.g. a close back below the hammer’s low for a long. That is your stop; honour it. "Giving it room" past the invalidation point is how small planned losses become large ones.']],
  deep: [['Technique', 'The repeatable loop: find a level → wait for a reversal/continuation candle there → confirm → measure R:R → enter on the break with stop beyond the extreme → target the next level. Journal each by setup.'],
    ['Failure mode', 'Trading shapes without location, skipping confirmation, mis-placing stops, or ignoring reward-to-risk — the four reasons patterns "fail".'],
    ['In real charts', 'The best candlestick trades are confirmed reversals at confluence zones, with the higher-timeframe trend, on a volume spike, with a clean 2R+ target.']],
  src: ['Investopedia: How to Trade Candlestick Patterns', 'https://www.investopedia.com/trading/candlestick-charting-what-is-it/'] });

/* ---------------- Level 4: chart patterns & TA ---------------- */

STT('st-reversal', { name: 'Reversal chart patterns', cat: 'stpattern',
  blurb: `Chart patterns are larger structures — formed over many candles — that signal the odds of a trend reversing. Double tops/bottoms, head and shoulders, and their inverses are the classics. Each has a neckline whose break confirms the pattern and gives a measured target.`,
  facts: [['Double top/bottom', 'two failed pushes at a level'], ['Head & shoulders', 'three peaks, middle highest'], ['Confirm', 'break of the neckline'], ['Target', 'pattern height from the break']],
  cheat: [['Double top (M)', 'Two highs at ~same level → bearish reversal'], ['Double bottom (W)', 'Two lows at ~same level → bullish reversal'], ['Triple top/bottom', 'Three failed pushes → reversal'], ['Head & shoulders', 'Peak, higher peak, lower peak → bearish top'], ['Inverse H&S', 'Mirror → bullish bottom'], ['Neckline', 'The level connecting the troughs/peaks'], ['Confirmation', 'Decisive close through the neckline'], ['Measured move', 'Pattern height projected from the break'], ['Retest', 'Price often returns to the neckline → entry'], ['Volume', 'Often falls into the pattern, rises on the break']],
  sections: [
    ['Double top and double bottom', FIG2(
      FIG(chart({ w: 270, h: 200, lines: [{ data: [20, 20.8, 21.6, 22.3, 21.4, 20.6, 21.3, 22.25, 21.5, 20.5, 19.6] }], hlines: [{ p: 20.5, label: 'neckline', cls: 'stc-sup' }], notes: [{ i: 3, p: 22.7, text: 'top 1', anchor: 'middle' }, { i: 7, p: 22.7, text: 'top 2', anchor: 'middle' }] }), 'Double top (M): two highs at the same level fail; a break below the neckline confirms the reversal.'),
      FIG(chart({ w: 270, h: 200, lines: [{ data: [22, 21.2, 20.4, 19.7, 20.6, 21.4, 20.7, 19.75, 20.5, 21.5, 22.4] }], hlines: [{ p: 21.5, label: 'neckline', cls: 'stc-res' }], notes: [{ i: 3, p: 19.3, text: 'bottom 1', anchor: 'middle' }, { i: 7, p: 19.35, text: 'bottom 2', anchor: 'middle' }] }), 'Double bottom (W): two lows hold the same level; a break above the neckline confirms the reversal.'))],
    ['Head and shoulders (and inverse)', FIG2(
      FIG(chart({ w: 270, h: 200, lines: [{ data: [18, 18.8, 19.8, 20.6, 19.8, 19.3, 20.4, 21.9, 20.3, 19.4, 20.2, 19.6, 18.9] }], hlines: [{ p: 19.35, label: 'neckline', cls: 'stc-res' }], notes: [{ i: 3, p: 20.9, text: 'LS', anchor: 'middle' }, { i: 7, p: 22.3, text: 'head', anchor: 'middle' }, { i: 10, p: 20.6, text: 'RS', anchor: 'middle' }] }), 'Head & shoulders (bearish top): a peak, a higher peak, a lower peak. Break of the neckline confirms.'),
      FIG(chart({ w: 270, h: 200, lines: [{ data: [22, 21.2, 20.2, 19.4, 20.2, 20.7, 19.6, 18.1, 19.7, 20.6, 19.8, 20.4, 21.1] }], hlines: [{ p: 20.65, label: 'neckline', cls: 'stc-sup' }], notes: [{ i: 3, p: 19.0, text: 'LS', anchor: 'middle' }, { i: 7, p: 17.7, text: 'head', anchor: 'middle' }, { i: 10, p: 19.4, text: 'RS', anchor: 'middle' }] }), 'Inverse head & shoulders (bullish bottom): the mirror image; break above the neckline confirms.'))],
    ['How to trade a reversal pattern', OL([`<b>Spot the structure:</b> two equal highs/lows (double), or three peaks with the middle highest (H&S), after a clear prior trend.`, `<b>Draw the neckline:</b> the level connecting the intervening trough(s)/peak(s).`, `<b>Wait for the break:</b> a <b>decisive close</b> through the neckline confirms the pattern — not a wick poke.`, `<b>Enter:</b> on the break, or (lower risk) on the <b>retest</b> of the neckline from the other side.`, `<b>Target:</b> project the <b>pattern height</b> (top to neckline) from the break point. <b>Stop:</b> beyond the right shoulder / second top.`])],
    ['Volume and reliability', PP(`Classic reversals often show <b>declining volume</b> as the pattern forms (the trend losing fuel) and a <b>volume surge on the neckline break</b> (the reversal gaining conviction). A break on weak volume is more likely to fail. These are <b>probabilities, not certainties</b> — patterns fail regularly, which is exactly why the neckline break (confirmation) and a stop beyond the structure are mandatory, and why you size each trade so a failure is a small, survivable loss.`)]
  ],
  edge: [`An unconfirmed pattern (no neckline break) is just a drawing — many "double tops" resume the uptrend. Wait for the break.`, `A wick through the neckline is not a break; require a decisive close (and ideally volume).`, `Patterns fail often — always use a stop beyond the structure and size for a loss.`, `Forcing patterns onto the chart (seeing H&S everywhere) is confirmation bias; the cleanest, most obvious ones work best.`, `The measured-move target is a guideline, not a promise — price may fall short or overshoot.`],
  faq: [['When is a reversal pattern actually confirmed?', PP(`On a <b>decisive close through the neckline</b> — the level connecting the pattern’s intervening troughs (double top / H&S) or peaks (double bottom / inverse H&S). Before that break the pattern is just a possibility; many "double tops" never break and the uptrend continues. The neckline break is the trigger; a retest of it from the other side often offers a lower-risk entry.`)],
    ['How do I set a target on these patterns?', PP(`Use the <b>measured move</b>: take the pattern’s height (from the top/head down to the neckline) and project it from the break point. For a head and shoulders, measure head-to-neckline and subtract from the break. It is a <b>guideline</b> — price frequently stalls near prior support/resistance along the way, so combine the measured target with visible structure.`)],
    ['Why does volume matter for chart patterns?', PP(`Volume reveals conviction. A reversal is more trustworthy when volume <b>fades</b> as the old trend’s pattern forms (buyers/sellers exhausting) and <b>surges on the neckline break</b> (new side committing). A neckline break on <i>low</i> volume is a common failure/fakeout. Volume is confirmation, not a standalone signal, but it meaningfully filters weak breaks.`)]],
  qs: [SQ('A head and shoulders top is confirmed when…', ['The head forms', 'Price closes decisively below the neckline', 'The right shoulder appears', 'Volume rises'], 1, 'The neckline break (decisive close) is the confirmation; before it the pattern can fail.'),
    SQ('How is the price target for these reversal patterns typically estimated?', ['Guesswork', 'Project the pattern’s height from the neckline break (measured move)', 'Always 10%', 'The previous close'], 1, 'The measured move projects the pattern height from the breakout point as a target guideline.')]
});
DP('st-reversal', {
  fu: [['What is a neckline retest and why trade it?', 'After the neckline breaks, price often returns to it — old support becomes resistance (or vice versa) — before continuing. Entering on a successful retest gives a tighter stop (just beyond the neckline) and confirmation that the break held, at the cost of sometimes missing trades that don’t retest.'],
    ['Do double/triple tops need the highs to be exactly equal?', 'No — "roughly equal" is enough; think zones. A triple top (three failed pushes) shows even more supply than a double. The key is repeated rejection at a level followed by a neckline break, not millimetre-perfect highs.'],
    ['How often do these patterns fail?', 'Often enough that confirmation and stops are mandatory — no pattern is a sure thing. Their edge is probabilistic: a confirmed, clean pattern with volume and a sensible target has favourable odds, but you will still lose a meaningful share, so position sizing carries the strategy.']],
  deep: [['Technique', 'Trade only clean, obvious patterns after a real prior trend; wait for the neckline close, enter on break or retest, stop beyond the structure, target the measured move but respect intervening S/R.'],
    ['Failure mode', 'Trading unconfirmed patterns, seeing patterns that are not there (bias), or ignoring volume and stops.'],
    ['In real charts', 'Head and shoulders and double tops/bottoms at major higher-timeframe levels, with fading volume into the pattern and a volume surge on the break, are among the most-watched reversal setups.']],
  src: ['StockCharts ChartSchool: Chart Patterns (Reversal)', 'https://chartschool.stockcharts.com/table-of-contents/chart-analysis/chart-patterns'] });

STT('st-continuation', { name: 'Continuation chart patterns', cat: 'stpattern',
  blurb: `Continuation patterns are pauses — the trend catches its breath before resuming. Triangles, flags, pennants, wedges and the cup-and-handle let you join an existing trend at a lower-risk point, with a clean breakout entry and a measured target.`,
  facts: [['Flag/pennant', 'brief pause after a sharp move'], ['Triangles', 'converging range → breakout'], ['Trade', 'breakout in the trend direction'], ['Target', 'often the prior move’s size']],
  cheat: [['Bull/bear flag', 'Sharp move (pole) + small counter-trend channel → continues'], ['Pennant', 'Pole + small symmetrical triangle → continues'], ['Ascending triangle', 'Flat top + rising lows → usually breaks up'], ['Descending triangle', 'Flat bottom + falling highs → usually breaks down'], ['Symmetrical triangle', 'Converging; breaks in the trend direction (usually)'], ['Rising/falling wedge', 'Wedge against trend; often reverses the wedge'], ['Rectangle', 'Sideways range; trade the breakout'], ['Cup & handle', 'Rounded base + small dip → bullish continuation'], ['Entry', 'Breakout close (and/or retest)'], ['Target', 'Flag: pole height; triangle: widest width']],
  sections: [
    ['Flags and pennants (the trader’s favourite)', FIG2(
      FIG(chart({ w: 270, h: 200, lines: [{ data: [19, 19.6, 20.4, 21.4, 22.4, 22.2, 21.9, 22.1, 21.8, 22.0, 22.9, 23.8] }], tlines: [{ from: [4, 22.5], to: [9, 22.1], dash: true }, { from: [5, 22.1], to: [9, 21.7], dash: true }], notes: [{ i: 2, p: 21.0, text: 'pole', anchor: 'middle' }, { i: 7, p: 22.6, text: 'flag', anchor: 'middle' }] }), 'Bull flag: a sharp rally (pole), then a small downward-drifting pause (flag), then breakout. Target ≈ the pole’s height added to the breakout.'),
      FIG(chart({ w: 270, h: 200, lines: [{ data: [19, 19.6, 20.4, 21.4, 22.4, 22.0, 21.7, 22.0, 21.9, 22.05, 22.95, 23.9] }], tlines: [{ from: [4, 22.5], to: [9, 22.15], dash: true }, { from: [5, 21.5], to: [9, 21.95], dash: true }], notes: [{ i: 7, p: 22.7, text: 'pennant', anchor: 'middle' }] }), 'Pennant: same idea, but the pause forms a small symmetrical triangle instead of a channel.'))],
    ['Triangles', FIG2(
      FIG(chart({ w: 270, h: 200, lines: [{ data: [19, 20.2, 19.6, 20.6, 20.0, 20.8, 20.4, 21.0, 20.75, 21.05, 21.6, 22.3] }], hlines: [{ p: 21.0, label: 'flat top', cls: 'stc-res' }], tlines: [{ from: [0, 19.0], to: [9, 20.8] }], notes: [{ i: 4, p: 18.8, text: 'ascending', anchor: 'middle' }] }), 'Ascending triangle: flat resistance + rising lows (demand building) → usually breaks up.'),
      FIG(chart({ w: 270, h: 200, lines: [{ data: [23, 21.8, 22.4, 21.3, 21.9, 21.0, 21.4, 20.9, 21.1, 20.95, 20.3, 19.5] }], hlines: [{ p: 20.9, label: 'flat bottom', cls: 'stc-sup' }], tlines: [{ from: [0, 23.0], to: [9, 21.1] }], notes: [{ i: 4, p: 23.1, text: 'descending', anchor: 'middle' }] }), 'Descending triangle: flat support + falling highs (supply building) → usually breaks down.'))],
    ['Cup and handle', FIG(chart({ w: 560, h: 210, lines: [{ data: [22, 21.2, 20.4, 19.9, 19.7, 19.75, 20.0, 20.5, 21.2, 21.8, 22.1, 22.0, 21.7, 21.85, 22.4, 23.2] }], hlines: [{ p: 22.1, label: 'rim / breakout level', cls: 'stc-res' }], notes: [{ i: 4, p: 19.4, text: 'cup', anchor: 'middle' }, { i: 12, p: 21.4, text: 'handle', anchor: 'middle' }] }), 'Cup and handle: a rounded recovery (cup) then a small pullback (handle). A breakout above the rim resumes the uptrend.')],
    ['Trading continuation patterns', OL([`<b>Identify the prior trend</b> and the pause (flag/triangle/cup) forming <i>with</i> it.`, `<b>Enter on the breakout</b> in the trend’s direction — a decisive close through the pattern boundary (optionally wait for a retest).`, `<b>Target:</b> flags/pennants → add the <b>pole height</b> to the breakout; triangles → project the <b>widest part</b> of the triangle; cup & handle → add the cup depth.`, `<b>Stop:</b> just inside/beyond the pattern (e.g. below the flag low, below the triangle’s last higher low).`, `<b>Volume:</b> ideally contracts during the pause and <b>expands on the breakout</b>.`])]
  ],
  edge: [`Breakouts fail (fakeouts) — require a decisive close and watch for volume expansion; consider entering on the retest.`, `A flag that drifts too far or too long isn’t a flag — healthy pauses are brief and shallow against a strong move.`, `Wedges are tricky: a rising wedge in an uptrend often breaks <i>down</i> (reversal), against intuition — know the exception.`, `Symmetrical triangles can break either way; bias toward the prevailing trend but wait for the actual break.`, `Low-volume breakouts are the most failure-prone; volume expansion is key confirmation.`],
  faq: [['How do I set a target for a flag or triangle?', PP(`For <b>flags and pennants</b>, measure the <b>pole</b> (the sharp move before the pause) and add it to the breakout point — the continuation often travels a similar distance. For <b>triangles</b>, take the <b>widest part</b> of the triangle and project it from the breakout. These "measured moves" are guidelines; combine them with the next real support/resistance, where price may stall.`)],
    ['Why can a rising wedge be bearish?', PP(`A <b>rising wedge</b> has price grinding up into a narrowing range on <i>weakening</i> momentum — higher highs that are barely higher, on fading volume. It shows buyers running out of steam even as price ticks up, so it frequently breaks <b>downward</b>, even within an uptrend. Falling wedges mirror this (often bullish). Wedges are the main exception to "pattern continues the trend," so treat them carefully and wait for the break.`)],
    ['Breakout entry or retest entry?', PP(`<b>Breakout entry</b> (on the decisive close through the boundary) catches the move early but suffers more fakeouts. <b>Retest entry</b> (waiting for price to come back to the broken boundary and hold) confirms the break and offers a tighter stop, but you sometimes miss trades that never retest. Many swing traders prefer the retest for its better risk control; pick one and apply it consistently.`)]],
  qs: [SQ('A sharp rally, then a small downward-drifting pause, then a breakout higher, is a…', ['Head and shoulders', 'Bull flag (continuation)', 'Double top', 'Descending triangle'], 1, 'Pole + shallow counter-trend pause + breakout = bull flag, a continuation pattern.'),
    SQ('An ascending triangle (flat top, rising lows) most often breaks…', ['Downward', 'Upward (demand pushing into fixed supply)', 'Randomly', 'It never breaks'], 1, 'Rising lows into flat resistance show building demand, usually resolving upward.')]
});
DP('st-continuation', {
  fu: [['Why do continuation patterns offer good reward-to-risk?', 'They let you join a proven trend during a tight, low-volatility pause, so your stop (just beyond the small pattern) is close while the target (a full measured move) is far — a naturally favourable reward-to-risk compared with chasing an extended trend.'],
    ['What distinguishes a pennant from a symmetrical triangle?', 'Scale and context: a pennant is a brief, small converging pause right after a sharp pole (a continuation flag variant); a symmetrical triangle is a larger consolidation that can appear anywhere and may take longer to resolve. Pennants resolve fast in the trend direction.'],
    ['How do you avoid fakeout breakouts?', 'Require a decisive close beyond the boundary (not a wick), look for volume expansion on the break, and/or wait for a successful retest. Fakeouts on low volume that snap back into the pattern can themselves be faded.']],
  deep: [['Technique', 'Trade continuations with the trend: enter the breakout (or retest) of a flag/triangle, stop just inside the pattern, target the measured move, and demand volume expansion on the break.'],
    ['Failure mode', 'Trading breakouts on weak volume (fakeouts), mislabeling a reversal wedge as a continuation, or entering a "flag" that has drifted too far to still be a pause.'],
    ['In real charts', 'Bull/bear flags after strong moves are among the highest reward-to-risk continuation setups; clean triangles and cup-and-handles at the right place in a trend are reliable when volume confirms.']],
  src: ['StockCharts ChartSchool: Continuation Chart Patterns', 'https://chartschool.stockcharts.com/table-of-contents/chart-analysis/chart-patterns/flag-pennant-continuation'] });

STT('st-fib', { name: 'Fibonacci retracement & extension', cat: 'stpattern',
  blurb: `Fibonacci levels mark where pullbacks commonly pause and where trends often extend. They are not magic — they work partly because so many traders watch them — but as a tool for picking pullback entries and projecting targets, they are a staple of technical analysis.`,
  facts: [['Retracement', 'where pullbacks pause (38.2/50/61.8%)'], ['Extension', 'where trends may target (127/161.8%)'], ['Golden zone', '~50–61.8% pullback'], ['Use with', 'S/R and candles, not alone']],
  cheat: [['Retracement 23.6%', 'Shallow pullback — strong trend'], ['Retracement 38.2%', 'Common pullback in strong trends'], ['Retracement 50%', 'Not a Fib number but widely watched'], ['Retracement 61.8%', 'The "golden ratio" — deep but valid pullback'], ['Retracement 78.6%', 'Deep; beyond it the move is in question'], ['Extension 127.2/161.8%', 'Common profit targets beyond the prior high'], ['Draw retracement', 'Swing low → swing high (uptrend)'], ['Golden pocket', '~0.618–0.65 confluence zone'], ['Confluence', 'Fib + S/R + MA = strong zone'], ['Not standalone', 'A pause zone, needs a trigger']],
  sections: [
    ['Retracement: where pullbacks pause', FIG(chart({ w: 560, h: 250, candles: trend(16, 20, 0.0, 0.6, 3).concat(trend(10, 25, -0.28, 0.5, 9)),
      hlines: [{ p: 23.1, label: '38.2%', cls: '' }, { p: 22.3, label: '50%', cls: '' }, { p: 21.5, label: '61.8% (golden)', cls: 'stc-sup' }] }),
      'After an up-move from the swing low to the swing high, price retraces. The 38.2%, 50% and 61.8% levels are where pullbacks commonly pause — the ~50–61.8% "golden zone" is a favourite buy area in an uptrend (with a trigger).')],
    ['How to use Fibonacci', OL([`<b>Draw the retracement</b> across the last clean swing: from the swing <b>low to high</b> in an uptrend (or high to low in a downtrend).`, `<b>Watch the 38.2–61.8% zone</b> for the pullback to pause — especially the <b>~50–61.8% "golden zone."</b>`, `<b>Require a trigger:</b> a reversal candle, a trendline/level touch, or an indicator signal <i>in</i> the Fib zone — do not buy a level blindly.`, `<b>Project targets with extensions:</b> the <b>127.2%</b> and <b>161.8%</b> levels beyond the prior high are common profit objectives.`, `<b>Prize confluence:</b> a Fib level that lines up with horizontal support and a moving average is far stronger than the Fib level alone.`])],
    ['Why Fibonacci "works"', PP(`There is debate about whether markets have an inherent Fibonacci structure. The practical reason these levels matter is <b>self-fulfilling attention</b>: a huge number of traders and algorithms place orders around the 38.2%, 50% and 61.8% retracements, so reactions cluster there. That makes Fib levels useful <i>zones of interest</i> — but exactly because they are approximate and crowded, you treat them as <b>areas, not precise lines</b>, and always pair them with a confirmation trigger.`)],
    ['Extensions for targets', PP(`Once in a with-trend trade, <b>extension</b> levels project how far the next impulse might travel: the <b>127.2%</b> and <b>161.8%</b> of the prior swing are common take-profit zones, and price often stalls there. Combine extensions with visible structure (the next resistance) rather than relying on a single number — and measure the trade’s reward-to-risk before entering.`)]
  ],
  edge: [`Fib levels are zones, not exact prices — demanding a reaction to the decimal gets you wicked out.`, `A Fib level alone is not a signal; without a trigger (candle/level/indicator) it is just a line.`, `Drawing the retracement on the wrong swing (not a clean, obvious one) produces meaningless levels.`, `Deep retracements beyond ~78.6% often mean the move is failing — not a dip to buy.`, `Over-plotting every Fib on every swing clutters the chart; use it on the dominant swing.`],
  faq: [['Which Fibonacci level matters most?', PP(`In practice the <b>50% and 61.8%</b> retracements (the "golden zone") get the most attention for pullback entries in a trend, with <b>38.2%</b> common in strong trends. None is magic — they are <b>zones of interest</b> where many orders cluster. Use the zone to <i>anticipate</i> where a pullback may pause, then require a <b>trigger</b> (a reversal candle, a support confluence) before entering.`)],
    ['How do I use Fibs to set a profit target?', PP(`Use <b>extensions</b>: after a pullback, the <b>127.2%</b> and <b>161.8%</b> of the prior swing project where the next move may reach, and price often stalls there. Treat them as target zones and cross-check with the next visible resistance/support. As always, confirm the trade’s reward-to-risk (target distance vs stop distance) is worth taking before you enter.`)],
    ['Is Fibonacci actually predictive or just self-fulfilling?', PP(`Largely self-fulfilling — so many participants watch the same levels that reactions cluster there, which is reason enough to use them as zones. Whether markets have deeper Fibonacci structure is debated and not something to rely on. Treat Fib as one confluence input among several (with S/R, trend and candles), not a standalone forecasting tool.`)]],
  qs: [SQ('In an uptrend, the Fibonacci "golden zone" for a pullback entry is roughly…', ['0–23.6%', '~50–61.8%', '78.6–100%', 'Above 100%'], 1, 'The ~50–61.8% retracement is the favoured pullback-buy zone (with a trigger).'),
    SQ('How should Fibonacci levels be treated?', ['As exact prices that must hold', 'As zones of interest that need a confirmation trigger and work best with confluence', 'As guaranteed reversal points', 'As a standalone buy/sell system'], 1, 'Fibs are approximate, crowded zones — use them with a trigger and other confluence.')]
});
DP('st-fib', {
  fu: [['What is the "golden pocket"?', 'The small zone between roughly the 0.618 and 0.65 retracement, where many traders concentrate pullback entries. Reactions often cluster there, but it still needs a trigger and ideally confluence with horizontal support or a moving average.'],
    ['Do you draw Fibs on wicks or closes?', 'Either can work if applied consistently; many draw from the extreme wick of the swing low to the extreme wick of the swing high. Consistency matters more than the choice — and because levels are zones, small differences rarely change the trade.'],
    ['How do Fib extensions compare with measured moves from patterns?', 'They are complementary target tools. Pattern measured moves use the pattern’s height; Fib extensions use the prior swing. When an extension level coincides with a pattern target and a horizontal level, that confluence is a high-probability stall/target zone.']],
  deep: [['Technique', 'Draw the retracement on the dominant clean swing, watch the 50–61.8% zone for a reaction, enter on a trigger with confluence, and target the 127.2/161.8% extensions cross-checked with structure.'],
    ['Failure mode', 'Treating Fib levels as exact, trading them without a trigger, drawing them on noisy swings, or buying very deep retracements of a failing move.'],
    ['In real charts', 'The most reliable Fib trades occur where the golden zone overlaps horizontal support and a moving average, with a reversal candle confirming — pure confluence.']],
  src: ['StockCharts ChartSchool: Fibonacci Retracements', 'https://chartschool.stockcharts.com/table-of-contents/technical-indicators-and-overlays/technical-overlays/fibonacci-retracements'] });

STT('st-volume-gaps', { name: 'Volume analysis & gaps', cat: 'stpattern',
  blurb: `Price tells you what happened; volume tells you how much conviction was behind it. Learning to read volume confirms breakouts, warns of exhaustion, and validates patterns. Gaps — jumps between one candle's close and the next's open — are a related, high-information event.`,
  facts: [['Volume', 'conviction behind a move'], ['Breakout', 'trust it more on rising volume'], ['Climax', 'huge volume can mark exhaustion'], ['Gap', 'a jump between close and open']],
  cheat: [['Rising volume + trend', 'Healthy, confirmed move'], ['Falling volume + trend', 'Move losing steam — caution'], ['Breakout on high volume', 'More reliable'], ['Breakout on low volume', 'Suspect (fakeout risk)'], ['Volume climax', 'Spike + exhaustion → possible turn'], ['Common gap', 'In a range; usually fills quickly'], ['Breakaway gap', 'Starts a new move out of a base — significant'], ['Runaway gap', 'Mid-trend; shows strength'], ['Exhaustion gap', 'End of a move on huge volume → reversal risk'], ['Gap fill', 'Price often returns to fill the gap (not always)']],
  sections: [
    ['Volume confirms (or doubts) the move', FIG(chart({ w: 560, h: 150, bars: 20, lines: [{ data: [10, 10, 10, 10, 10, 10, 10, 10, 10, 10, 10, 10, 10, 10, 10, 10, 10, 10, 10, 10], cls: '' }], hlines: [{ p: 10, label: '', cls: '' }] }).replace('</svg>', (() => {
      // draw simple volume bars manually under a conceptual price break
      let bars = '', vols = [3, 3, 4, 3, 5, 4, 4, 6, 3, 4, 9, 11, 8, 10, 4, 3, 3, 4, 3, 3];
      vols.forEach((v, i) => { const x = 10 + (i + 0.5) * (502 / 20); bars += `<rect class="${i >= 10 && i <= 13 ? 'stc-mk-buy' : 'stc-ax'}" x="${(x - 7).toFixed(1)}" y="${(138 - v * 9).toFixed(1)}" width="12" height="${(v * 9).toFixed(1)}" opacity="${i >= 10 && i <= 13 ? '0.85' : '0.4'}"/>`; });
      return `<text class="stc-note" x="300" y="22">volume bars</text>${bars}</svg>`;
    })()), 'A breakout is far more trustworthy when it comes with a volume surge (highlighted). The same breakout on quiet volume is a common fakeout.')],
    ['What volume is telling you', TBL(['Volume behaviour', 'Interpretation'], [['Rises as price trends', 'Conviction — the move has fuel'], ['Falls as price trends', 'Fading interest — move may stall/reverse'], ['Surges on a breakout', 'Confirms the breakout'], ['Quiet on a breakout', 'Suspect — fakeout risk'], ['Huge spike after a long move', 'Possible climax/exhaustion — turn risk'], ['Dries up in a pullback', 'Healthy pause within a trend (good)']]) + PP(`Rule of thumb: <b>volume should expand in the direction of the trend/breakout and contract during pauses.</b> When volume and price disagree (price up, volume fading), be cautious.`)],
    ['Gaps and their meaning', TBL(['Gap type', 'Where', 'Meaning'], [['Common gap', 'Inside a range', 'Low information; usually fills quickly'], ['Breakaway gap', 'Out of a base/pattern', 'Significant — a new move beginning (often holds)'], ['Runaway (continuation) gap', 'Mid-trend', 'Strength; trend accelerating'], ['Exhaustion gap', 'After a long move, on huge volume', 'The last gasp — reversal risk']]) + PP(`"Gaps fill" is a <b>tendency, not a law</b>: common gaps fill often and fast; breakaway and runaway gaps may not fill for a long time, if ever. Volume helps classify a gap — a breakaway gap on heavy volume is meaningful; an exhaustion gap is a huge-volume spike at the end of a stretched move.`)],
    ['Using volume and gaps in practice', UL([`<b>Confirm breakouts</b> with volume expansion before trusting them.`, `<b>Doubt moves</b> where price rises but volume fades — momentum is leaving.`, `<b>Respect breakaway gaps</b> as new trends; be wary of <b>exhaustion gaps</b> after long runs.`, `Volume is a <b>confirmation tool</b>, not a standalone signal — pair it with price structure and patterns.`])]
  ],
  edge: [`"All gaps fill" is a myth — breakaway and runaway gaps can run for a long time; don’t fade them expecting an instant fill.`, `Volume conventions vary (forex has no central volume; crypto volume differs by venue) — interpret accordingly.`, `A low-volume breakout is the classic fakeout setup — demand volume expansion.`, `A single volume spike can be a climax (reversal) or a breakout (continuation) — context (after a long move vs out of a base) decides.`, `Don’t trade volume alone; it confirms price, it does not lead it.`],
  faq: [['How does volume confirm a breakout?', PP(`A genuine breakout usually comes with a <b>surge in volume</b> — many participants committing to the new direction. That expansion is your confirmation that the break is real rather than a stop-run fakeout. A breakout on <b>quiet</b> volume is far more likely to fail and reverse back into the range, so volume expansion is one of the most useful breakout filters.`)],
    ['Do gaps always get filled?', PP(`No — that is a common myth. <b>Common gaps</b> (inside ranges) do fill often and quickly. But <b>breakaway gaps</b> (out of a base) and <b>runaway gaps</b> (mid-trend) reflect real new demand/supply and can go unfilled for a long time, sometimes never. Classify the gap by its location and volume before assuming it will fill; trading "the gap must fill" blindly is a good way to fight a strong trend.`)],
    ['What is a volume climax?', PP(`An unusually large volume spike, typically after an extended move, where the last wave of buyers (or sellers) rushes in. It often marks <b>exhaustion</b> — the move running out of fresh participants — and precedes a pause or reversal. A climax is a warning to tighten stops or take profit, confirmed by a reversal candle/pattern, not an automatic signal to trade the other way.`)]],
  qs: [SQ('A breakout above resistance is most trustworthy when accompanied by…', ['Falling volume', 'A surge in volume', 'No volume change', 'A gap down'], 1, 'Volume expansion confirms commitment to the breakout; quiet volume suggests a fakeout.'),
    SQ('Which statement about gaps is correct?', ['All gaps always fill quickly', 'Breakaway and runaway gaps may not fill for a long time, unlike common gaps', 'Gaps have no meaning', 'Exhaustion gaps signal strong continuation'], 1, 'Gap-fill is a tendency; significant breakaway/runaway gaps often run, while common gaps fill fast.')]
});
DP('st-volume-gaps', {
  fu: [['Why does forex have no "real" volume?', 'Forex is decentralised (no single exchange), so there is no consolidated volume figure — platforms show tick volume (number of price changes) as a proxy. It is still useful for relative activity but is not true traded volume like on a stock exchange.'],
    ['What is a volume dry-up in a pullback?', 'When volume contracts sharply during a counter-trend pullback, it signals the pullback lacks conviction — sellers (in an uptrend) are not committed — which supports a continuation entry when the trend resumes on expanding volume.'],
    ['How do you tell a breakaway gap from an exhaustion gap?', 'Location and context: a breakaway gap launches a new move out of a base/pattern (bullish/bearish start), while an exhaustion gap appears after a long, stretched move, often on climactic volume, signalling the move is ending. Both can be big; where they occur distinguishes them.']],
  deep: [['Technique', 'Overlay volume on every chart: demand expansion to trust breakouts and trends, treat fading volume as a warning, and classify gaps by location and volume before acting.'],
    ['Failure mode', 'Trading low-volume breakouts, fading unfilled breakaway/runaway gaps expecting a fill, or treating a single volume spike without context.'],
    ['In real charts', 'The highest-quality breakouts show a clear volume surge; sustained trends show volume expanding on impulses and drying up on pullbacks; climactic volume after long runs marks turns.']],
  src: ['StockCharts ChartSchool: Gaps and Volume', 'https://chartschool.stockcharts.com/table-of-contents/chart-analysis/gaps-and-gap-analysis'] });
